'use client'

import { useMessageContext } from '@/app/context/MessageContext'
import { RiSendInsLine } from 'react-icons/ri'

export default function SendButton() {
	const { message, setChatContent, chatContent } = useMessageContext()
	const sendMessage = () =>
		setChatContent([...chatContent, { username: 'Pavel', date: new Date(), msg: 'Hello' }])

	return (
		<button
			className={`${!message.msg ? 'bg-gray-500 cursor-not-allowed' : 'bg-white'} p-2 rounded-2xl cursor-pointer`}
			onClick={() => sendMessage()}
			disabled={!message.msg}
		>
			<RiSendInsLine
				size={30}
				color="black"
			/>
		</button>
	)
}
